impl fhir_validation::r5::R5ValidatableAsync for Duration {
    async fn validate_bindings_async(
        &self,
        validator: &fhir_validation::Validator,
        terminology: Option<&dyn fhir_validation::TerminologyService>,
    ) -> Vec<fhir_validation::ValidationIssue> {
        let mut issues = Vec::new();
        issues.extend(validator.apply_r5_bindings_async(self, DURATION_BINDINGS.as_slice(), terminology).await);
        issues
    }
    }

