static EVIDENCE_VARIABLE_CHARACTERISTIC_INVARIANTS: std::sync::LazyLock<Vec<fhir_validation_types::InvariantDef>> = std::sync::LazyLock::new(|| vec![
    fhir_validation_types::InvariantDef {
        key: "ele-1".to_string(),
        severity: fhir_validation_types::Severity::Error,
        path: "EvidenceVariable.characteristic".to_string(),
        expression: "hasValue() or (children().count() > id.count())".to_string(),
        human: "All FHIR elements must have a @value or children".to_string(),
    },
    fhir_validation_types::InvariantDef {
        key: "evv-1".to_string(),
        severity: fhir_validation_types::Severity::Error,
        path: "EvidenceVariable.characteristic".to_string(),
        expression: "(definitionReference.count() + definitionCanonical.count() + definitionCodeableConcept.count() + definitionId.count() + definitionByTypeAndValue.count() + definitionByCombination.count())  < 2".to_string(),
        human: "In a characteristic, at most one of these six elements shall be used: definitionReference or definitionCanonical or definitionCodeableConcept or definitionId or definitionByTypeAndValue or definitionByCombination".to_string(),
    },
]);

